function normalizeRunResult(result) {
  return {
    changes: Number(result && result.changes ? result.changes : 0),
    lastInsertRowid: result && Object.prototype.hasOwnProperty.call(result, "lastInsertRowid")
      ? result.lastInsertRowid
      : undefined,
  };
}

function createStatementWrapper(statement) {
  return {
    run(params = {}) {
      return normalizeRunResult(statement.run(params));
    },
    get(params = {}) {
      return statement.get(params);
    },
    all(params = {}) {
      return statement.all(params);
    },
  };
}

function createDatabaseAdapter(rawDb, metadata) {
  return {
    driverName: metadata.driverName,
    filePath: metadata.filePath,
    exec(sql) {
      rawDb.exec(sql);
    },
    prepare(sql) {
      return createStatementWrapper(rawDb.prepare(sql));
    },
    transaction(work) {
      rawDb.exec("BEGIN IMMEDIATE");
      try {
        const result = work(this);
        rawDb.exec("COMMIT");
        return result;
      } catch (error) {
        try {
          rawDb.exec("ROLLBACK");
        } catch (rollbackError) {
          error.rollbackError = rollbackError;
        }
        throw error;
      }
    },
    pragma(statement) {
      const pragmaSql = statement.trim().toUpperCase().startsWith("PRAGMA")
        ? statement
        : `PRAGMA ${statement}`;
      return rawDb.prepare(pragmaSql).all();
    },
    close() {
      rawDb.close();
    },
  };
}

