"use strict";

const path = require("node:path");

const RUNTIME_PROFILES = Object.freeze(["local", "onprem", "on-prem", "hybrid"]);

function normalizeRuntimeProfile(value) {
  const profile = String(value || "local").trim().toLowerCase();
  if (!RUNTIME_PROFILES.includes(profile)) {
    throw new Error(`CASEWORK_RUNTIME_PROFILE must be one of ${RUNTIME_PROFILES.join(", ")}`);
  }
  return profile === "on-prem" ? "onprem" : profile;
}

function resolveInsideRoot(rootPath, childPath, label) {
  const root = path.resolve(rootPath);
  const target = path.resolve(childPath);
  const relative = path.relative(root, target);
  if (relative === "" || (!relative.startsWith("..") && !path.isAbsolute(relative))) {
    return target;
  }
  throw new Error(`${label} must resolve inside CASEWORK_DATA_ROOT`);
}

function assertPortableFileReference(filePath, label) {
  if (filePath == null || filePath === "") {
    return null;
  }

  const value = String(filePath);
  const normalized = path.posix.normalize(value.replace(/\\/g, "/"));
  const segments = value.replace(/\\/g, "/").split("/");
  if (
    path.isAbsolute(value)
    || normalized === "."
    || normalized === ".."
    || normalized.startsWith("../")
    || normalized.includes("/../")
    || segments.includes("..")
  ) {
    throw new Error(`${label} must be a portable relative path inside its configured root`);
  }
  return normalized;
}

function resolveCaseworkConfig(env = process.env, cwd = process.cwd()) {
  const runtimeProfile = normalizeRuntimeProfile(env.CASEWORK_RUNTIME_PROFILE);
  const dataRoot = path.resolve(env.CASEWORK_DATA_ROOT || path.join(cwd, ".casework"));
  const sqlitePath = resolveInsideRoot(
    dataRoot,
    env.CASEWORK_SQLITE_PATH || path.join(dataRoot, "casework.sqlite"),
    "CASEWORK_SQLITE_PATH",
  );
  const uploadsRoot = resolveInsideRoot(
    dataRoot,
    env.CASEWORK_UPLOADS_ROOT || path.join(dataRoot, "uploads"),
    "CASEWORK_UPLOADS_ROOT",
  );
  const exportsRoot = resolveInsideRoot(
    dataRoot,
    env.CASEWORK_EXPORTS_ROOT || path.join(dataRoot, "exports"),
    "CASEWORK_EXPORTS_ROOT",
  );

  return Object.freeze({
    runtimeProfile,
    dataRoot,
    sqlitePath,
    uploadsRoot,
    exportsRoot,
  });
}

module.exports = {
  RUNTIME_PROFILES,
  normalizeRuntimeProfile,
  resolveInsideRoot,
  assertPortableFileReference,
  resolveCaseworkConfig,
};

